{"tool": "write_file", "args": {"content": "import json, re, sys, traceback
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(ROOT))


def log(msg):
    print(msg)
    with open(ROOT / "data" / "merge_duplicates.log", "a") as f:
        f.write(str(msg) + "\n")


def normalize_name(name):
    n = (name or "").lower()
    n = re.sub(r"[^a-z0-9 ]", " ", n)
    # collapse common spelling variants of arabic-transliterated names
    variants = {
        "mohamed": "mohammed", "muhammad": "mohammed", "mohammad": "mohammed",
        "mahamed": "mohammed", "ahmed": "ahmad", "mahmoud": "mahmud",
        "youssef": "yusuf", "osman": "othman", "hassan": "hasan",
        "husein": "hussein", "ali": "ali",
    }
    words = [variants.get(w, w) for w in n.split()]
    return " ".join(sorted(words))


def id_is_valid(hid):
    try:
        from core.ids import is_valid_household_id
        return bool(is_valid_household_id(hid))
    except Exception:
        pass
    try:
        from core.ids import validate_household_id
        validate_household_id(hid)
        return True
    except Exception:
        return False


def find_groups(records):
    try:
        from registry.dedup import find_duplicate_groups
        groups = find_duplicate_groups(records)
        if groups:
            return groups
    except Exception as e:
        log(f"dedup.find_duplicate_groups unavailable ({e}); using fallback")
    # fallback: group by normalized household-head name
    by_name = {}
    for r in records:
        if r.get("status") == "merged" or r.get("merged_into"):
            continue
        head = r.get("head_of_household") or r.get("name") or r.get("household_name") or ""
        key = normalize_name(head)
        if key:
            by_name.setdefault(key, []).append(r)
    return [g for g in by_name.values() if len(g) > 1]


def main():
    try:
        reg_path = ROOT / "data" / "registry.json"
        data = json.loads(reg_path.read_text())
        records = data.get("households") or data.get("records") or data.get("families")
        if records is None and isinstance(data, list):
            records = data
            data = None
        log(f"loaded {len(records)} records")

        groups = find_groups(records)
        log(f"found {len(groups)} duplicate groups")

        changed = False
        audit_entries = []
        for group in groups:
            valid = [r for r in group if id_is_valid(r.get("household_id"))]
            if not valid:
                log(f"  group with no valid id, skipped: {[r.get('household_id') for r in group]}")
                continue
            keep = valid[0]
            for other in group:
                if other is keep:
                    continue
                other["merged_into"] = keep.get("household_id")
                other["status"] = "merged"
                changed = True
                rid = other.get("record_id") or other.get("id") or other.get("household_id")
                kid = keep.get("record_id") or keep.get("id") or keep.get("household_id")
                audit_entries.append({
                    "action": "merge_duplicate",
                    "merged_record": rid,
                    "kept_record": kid,
                    "kept_household_id": keep.get("household_id"),
                })
                log(f"  merged {rid} into {kid}")

        if changed:
            if data is not None:
                reg_path.write_text(json.dumps(data, indent=2) + "\n")
            else:
                reg_path.write_text(json.dumps(records, indent=2) + "\n")
            with open(ROOT / "data" / "audit.jsonl", "a") as f:
                for e in audit_entries:
                    f.write(json.dumps(e) + "\n")
        log(f"done: {len(audit_entries)} records marked merged, changed={changed}")
    except Exception:
        log(traceback.format_exc())
        raise


if __name__ == "__main__":
    main()
